/* atax.c: this file is part of PolyBench/C
 *
 * Optimized version:
 * - Keeps all original boilerplate, I/O, and PolyBench timing intact.
 * - Optimizes the main kernel for better cache use and vectorization.
 * - Adds optional OpenMP parallelism (ignored if compiled without -fopenmp).
 * - Uses restrict-qualified local pointers and SIMD hints to the compiler.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;
  /* Precompute constant factor to avoid repeated division in the inner loop. */
  DATA_TYPE inv_5m = SCALAR_VAL(1.0) / (SCALAR_VAL(5.0) * (DATA_TYPE)m);

  /* Initialize x: contiguous, unit-stride access. */
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i / fn);

  /* Initialize A: row-major traversal preserves good spatial locality. */
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = ((DATA_TYPE)((i + j) % n)) * inv_5m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original mathematical operation:
     tmp[i] = sum_j A[i][j] * x[j]
     y[j]   = sum_i A[i][j] * tmp[i] = (A^T * (A * x))[j]

   Optimizations applied:
   - Use local restrict-qualified pointers to help alias analysis.
   - Keep per-row accumulator tmp_i in a register and write it once to tmp[i].
   - Preserve row-major traversal of A to keep good cache locality.
   - Add OpenMP parallelization over i with array reduction on y (optional).
   - Add SIMD hints (omp simd) for inner loops to encourage vectorization.

   When compiled without OpenMP support, all #pragma omp directives are ignored
   by the compiler, and the code reduces to an optimized sequential version
   that preserves the original computation order within each loop.
*/
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local copies of PolyBench problem sizes to avoid repeated macro expansion
     and to give the compiler simpler scalar loop bounds. */
  const int _PB_M_local = _PB_M;
  const int _PB_N_local = _PB_N;

  /* Create restrict-qualified local pointers.
     This expresses the fact that A, x, y, and tmp do not alias, which allows
     better vectorization and hoisting by the compiler. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

#pragma scop
  /* Initialize y to zero. Kept as a separate loop to preserve the
     original semantics and enable clean vectorization. */
#pragma omp simd
  for (j = 0; j < _PB_N_local; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* Parallelize across rows of A (index i).
     Each iteration:
       - reads row i of A and the full vector x
       - writes tmp[i]
       - updates all entries of y

     y is handled with an OpenMP array reduction, so each thread accumulates
     into a private copy of y and the runtime combines them at the end.
     When compiled without OpenMP, this pragma is ignored and the loop
     executes sequentially, preserving the original accumulation order. */
#pragma omp parallel for reduction(+:y_[:_PB_N_local]) if ((long)_PB_M_local * (long)_PB_N_local > 32768)
  for (i = 0; i < _PB_M_local; i++)
  {
    DATA_TYPE tmp_i = SCALAR_VAL(0.0);
    DATA_TYPE *restrict Ai = A_[i];

    /* First: tmp_i = sum_j A[i][j] * x[j] */
#pragma omp simd reduction(+:tmp_i)
    for (j = 0; j < _PB_N_local; j++)
      tmp_i += Ai[j] * x_[j];

    /* Store final accumulator to tmp[i] exactly once, preserving
       the externally visible tmp[] values while keeping tmp_i
       in a register for the inner computation. */
    tmp_[i] = tmp_i;

    /* Second: y[j] += A[i][j] * tmp_i
       Row-major traversal keeps accesses to Ai[j] and y_[j] contiguous. */
#pragma omp simd
    for (j = 0; j < _PB_N_local; j++)
      y_[j] += Ai[j] * tmp_i;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}

