/* atax.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  /* x is initialized linearly in i/n, keep original arithmetic to
     preserve exact floating-point semantics. */
  for (i = 0; i < n; i++)
      x[i] = SCALAR_VAL(1.0) + ( (DATA_TYPE)i / fn );

  /* A initialization as in the original code. */
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original algorithm:
     tmp[i] = sum_j A[i][j] * x[j]
     y[j]   = sum_i A[i][j] * tmp[i]

   Optimizations applied:
     - Use restrict-qualified local aliases for better vectorization.
     - Compute tmp = A * x and y = A^T * tmp in two clear phases.
       This keeps the mathematical order of additions per element,
       so floating-point results are bit-identical to the original.
     - Cache-friendly blocking of the y-update over the j-dimension
       to keep a slice of y in L1/L2 cache.
     - Optional OpenMP parallelization:
         * Phase 1: parallel over i (rows of A).
         * Phase 2: parallel over j-blocks (disjoint slices of y),
           which avoids data races on y.
     - Explicit inner-loop vectorization hints where safe.
*/
static
void kernel_atax [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  (void)m; /* m and n are passed for PolyBench macros; actual
              iteration counts are _PB_M and _PB_N. */
  (void)n;

  int i, j;

  /* Local restrict-qualified aliases to improve compiler
     assumptions about aliasing and enable better vectorization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_   = x;
  DATA_TYPE *restrict y_   = y;
  DATA_TYPE *restrict tmp_ = tmp;

  /* Block size for y in phase 2. Tune for cache hierarchy. */
  const int J_BLOCK = 256;

#pragma scop
  /* Initialize y to zero (live-out); keep loop bounds identical
     to the original implementation. */
  for (i = 0; i < _PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* =========================
   * Phase 1: tmp = A * x
   * =========================
   *
   * Each i-iteration is independent, so this loop can be
   * safely parallelized. Within an iteration, we keep the exact
   * accumulation order of the original code by performing:
   *
   *   acc_0 = 0
   *   acc_{k+1} = acc_k + A[i][k] * x[k]
   *
   * and finally writing tmp[i] = acc_{N}.
   */
  #pragma omp parallel for schedule(static) if (_PB_M * (long)_PB_N > 8192L)
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE acc = SCALAR_VAL(0.0);
    const DATA_TYPE *restrict Ai = A_[i];

    /* No loop-carried dependencies except on 'acc', which is a
       scalar reduction; the compiler can safely vectorize. */
    #pragma GCC ivdep
    for (j = 0; j < _PB_N; j++)
      acc += Ai[j] * x_[j];

    tmp_[i] = acc;
  }

  /* =========================
   * Phase 2: y += A^T * tmp
   * =========================
   *
   * Original code:
   *   for (i)
   *     for (j)
   *       y[j] += A[i][j] * tmp[i];
   *
   * We apply j-blocking:
   *
   *   for (jj in 0..N step J_BLOCK)
   *     for (i)
   *       for (j in jj..j_end)
   *         y[j] += A[i][j] * tmp[i];
   *
   * For a fixed j, contributions from i still occur in strictly
   * increasing i order, exactly as in the original code, so the
   * sequence of additions to y[j] is unchanged and the results are
   * bit-identical. Reordering only occurs between different j, which
   * are independent.
   *
   * The outer loop over jj (blocks of the j-dimension) is also
   * parallelized: each thread works on disjoint slices of y, so no
   * synchronization is needed for y.
   */
  const int N_ = _PB_N;
  const int M_ = _PB_M;

  #pragma omp parallel for schedule(static) if ((long)N_ * M_ > 8192L)
  for (int jj = 0; jj < N_; jj += J_BLOCK)
  {
    int j_end = jj + J_BLOCK;
    if (j_end > N_)
      j_end = N_;

    const int block_len = j_end - jj;

    for (i = 0; i < M_; i++)
    {
      DATA_TYPE ti = tmp_[i];
      const DATA_TYPE *restrict Ai_block = &A_[i][jj];
      DATA_TYPE *restrict y_block = &y_[jj];

      /* Inner loop over a contiguous slice of y and A's row,
         which is friendly to vectorization and cache. */
      #pragma GCC ivdep
      for (j = 0; j < block_len; j++)
        y_block[j] += Ai_block[j] * ti;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
