/* atax.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>   /* for polybench_alloc_data/polybench_free_data helper */
#ifdef _OPENMP
# include <omp.h>     /* OpenMP parallelism (used only when compiled with -fopenmp) */
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization.
 *
 * Optimization notes:
 * - Use local restrict-qualified pointers to help the compiler with alias
 *   analysis and enable better vectorization.
 * - Precompute the denominator (5 * m) once instead of on every iteration.
 * - Keep the traversal order (i outer, j inner) to preserve row-major access.
 */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Create restrict-qualified local views to help the optimizer.
     These are semantically equivalent because the allocated arrays
     in main() do not alias each other. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;

  /* Initialize x. */
  for (i = 0; i < n; i++)
    x_[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i / fn);

  /* Precompute constant divisor once. */
  const DATA_TYPE denom = SCALAR_VAL(5.0) * (DATA_TYPE)m;

  /* Initialize A with row-major traversal (good cache locality). */
  for (i = 0; i < m; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    for (j = 0; j < n; j++)
      Ai[j] = (DATA_TYPE)((i + j) % n) / denom;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 * - Introduce restrict-qualified local pointer aliases to tell the
 *   compiler that A, x, y, and tmp do not alias, enabling better
 *   vectorization and keeping accumulators in registers.
 * - Use a scalar temporary (tmp_i) per row i to avoid repeated
 *   stores to tmp[i] inside the inner loop.
 * - Keep row-major traversal (i outer, j inner) for good cache
 *   behavior on A in both phases of the computation.
 * - Provide an OpenMP-parallel implementation that:
 *     * Parallelizes over rows i.
 *     * Uses a thread-private accumulation buffer for y to avoid
 *       data races.
 *     * Reduces the thread-private y vectors into the final y in a
 *       second parallel loop.
 *   This preserves the mathematical result of the original code.
 *   (Floating-point round-off may differ slightly due to different
 *   summation orders.)
 */
static
__attribute__((noinline))
void kernel_atax (int m, int n,
                  DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                  DATA_TYPE POLYBENCH_1D(x,N,n),
                  DATA_TYPE POLYBENCH_1D(y,N,n),
                  DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  /* Create restrict-qualified local views.  The arrays allocated in
     main() are distinct, so this is semantically correct and allows
     the compiler to be more aggressive. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

  int i, j;

  /* As in the original code, explicitly initialize y to zero. */
  for (i = 0; i < _PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

#ifndef _OPENMP

  /* ===================== Sequential version ===================== */

  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute tmp[i] = A[i][:] * x[:] using a scalar accumulator
       to keep the reduction in registers. */
    DATA_TYPE tmp_i = SCALAR_VAL(0.0);
    for (j = 0; j < _PB_N; j++)
      tmp_i += Ai[j] * x_[j];

    tmp_[i] = tmp_i;

    /* y[:] += A[i][:] * tmp[i];  row-major traversal preserves
       good cache behavior for A and enables vectorization. */
    for (j = 0; j < _PB_N; j++)
      y_[j] += Ai[j] * tmp_i;
  }

#else  /* _OPENMP defined => use parallel version */

  /* ===================== Parallel version (OpenMP) =====================
   *
   * Strategy:
   *  - Split the outer loop over rows i across threads (#pragma omp for).
   *  - Each thread accumulates into its own private y buffer of length N,
   *    so there are no data races during the main computation.
   *  - At the end, reduce all thread-private y buffers into the final y.
   *
   * Memory usage:
   *  - Additional temporary storage is (num_threads * N) elements of
   *    DATA_TYPE, which is typically much smaller than the main A array
   *    and stays well below the "+50%" memory budget.
   */

  DATA_TYPE *y_priv = NULL; /* will hold num_threads * _PB_N elements */

  #pragma omp parallel
  {
    int tid, nthreads;
    DATA_TYPE *restrict y_local;

    /* One thread allocates the per-thread y buffer once we know how
       many threads participate in this parallel region. */
    #pragma omp single
    {
      nthreads = omp_get_num_threads();
      /* polybench_alloc_data returns 64-byte aligned memory, which is
         beneficial for SIMD vectorization on x86-64. */
      y_priv = (DATA_TYPE*)
        polybench_alloc_data((unsigned long long)nthreads *
                             (unsigned long long)_PB_N,
                             sizeof(DATA_TYPE));
    }
    /* Implicit barrier at end of single: all threads see y_priv set. */

    tid      = omp_get_thread_num();
    nthreads = omp_get_num_threads();  /* same value for all threads */
    y_local  = y_priv + (size_t)tid * (size_t)_PB_N;

    /* Initialize this thread's private y accumulator. */
    for (j = 0; j < _PB_N; j++)
      y_local[j] = SCALAR_VAL(0.0);

    /* Main computation: split the outer loop over i across threads. */
    #pragma omp for schedule(static)
    for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      /* Compute tmp[i] as row dot-product A[i][:] * x[:]. */
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
        tmp_i += Ai[j] * x_[j];

      tmp_[i] = tmp_i;

      /* Accumulate this row's contribution into the thread-local y. */
      for (j = 0; j < _PB_N; j++)
        y_local[j] += Ai[j] * tmp_i;
    }

    /* Reduce thread-local y buffers into the final y vector.
       The loop over j is also parallelized; for each j, we sum all
       per-thread contributions.
       Note: the order of floating-point additions differs from the
       purely sequential version, so results can differ in the last
       few bits due to round-off, but the mathematical result is the
       same. */
    #pragma omp for schedule(static)
    for (j = 0; j < _PB_N; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      for (int t = 0; t < nthreads; t++)
        sum += y_priv[(size_t)t * (size_t)_PB_N + j];
      y_[j] = sum;
    }
  } /* end parallel region */

  /* Free the temporary per-thread y buffer. */
  polybench_free_data(y_priv);

#endif /* _OPENMP */
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(x),
               POLYBENCH_ARRAY(y),
               POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
