 *  - Replace divisions by invariant values with multiplications by their
 *    reciprocals to reduce the number of expensive divide operations.
 *  - Use a row pointer for A to improve compiler optimization and cache use.
 */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  const DATA_TYPE fn        = (DATA_TYPE)n;
  const DATA_TYPE inv_fn    = SCALAR_VAL(1.0) / fn;
  const DATA_TYPE denom     = SCALAR_VAL(5.0) * (DATA_TYPE)m;
  const DATA_TYPE inv_denom = SCALAR_VAL(1.0) / denom;

  /* x[i] = 1 + i / n  ->  1 + i * (1/n) */
  for (i = 0; i < n; i++)
    x[i] = SCALAR_VAL(1.0) + (DATA_TYPE)i * inv_fn;

  /* A[i][j] = ((i + j) % n) / (5 * m)
   *        = ((i + j) % n) * (1 / (5 * m))
   */
  for (i = 0; i < m; i++)
  {
    DATA_TYPE* restrict Ai = A[i];
    for (j = 0; j < n; j++)
      Ai[j] = (DATA_TYPE)((i + j) % n) * inv_denom;
  }
}


/* DCE code. Must scan the entire live-out data.
