/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original algorithm:
 *   tmp[i] = sum_j A[i][j] * x[j]
 *   y[j]   = sum_i A[i][j] * tmp[i]
 *
 * This implementation preserves that computation but:
 *   - keeps y-initialization separate,
 *   - uses a per-thread private buffer y_local to enable safe OpenMP
 *     parallelization over rows without data races on y,
 *   - uses row pointers and local scalars for better cache and
 *     vectorization behavior.
 *
 * When compiled without OpenMP support, all #pragma omp directives are
 * ignored and the code executes sequentially, preserving the original
 * operation order and results.
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n),
                 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i;

  /* Use PolyBench loop bounds (may differ from raw m,n in some configs). */
  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

#pragma scop
  /* Initialize y to zero once, outside the main loops. */
  for (i = 0; i < Ndim; i++)
    y[i] = SCALAR_VAL(0.0);

  /* Parallel region over rows of A.
   * - Each thread accumulates into its own y_local buffer to avoid
   *   write conflicts.
   * - tmp[i] values are written exactly once per row, as in the
   *   original code.
   *
   * In a non-OpenMP build, this block is executed by a single thread
   * and behaves like a plain sequential loop nest.
   */
#pragma omp parallel
  {
    int i, j;

    /* Thread-private accumulation buffer for y.
     * Size is Ndim per thread; this stays well within the 50% extra
     * memory budget for typical PolyBench problem sizes.
     */
    DATA_TYPE y_local[Ndim];

    /* Initialize private buffer. */
    for (j = 0; j < Ndim; j++)
      y_local[j] = SCALAR_VAL(0.0);

    /* Distribute rows of A across threads. */
#pragma omp for schedule(static)
    for (i = 0; i < Mdim; i++)
    {
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);
      DATA_TYPE* restrict Ai = A[i];

      /* First pass: tmp[i] = dot(A[i, :], x)
       * Row-major access of A and contiguous access to x.
       */
#pragma GCC ivdep
      for (j = 0; j < Ndim; j++)
        tmp_i += Ai[j] * x[j];

      /* Store tmp[i] to preserve original live-out behavior. */
      tmp[i] = tmp_i;

      /* Second pass: y_local[j] += A[i][j] * tmp[i]
       * Row-major access again; this matches the original memory pattern
       * but writes into a thread-local buffer.
       */
#pragma GCC ivdep
      for (j = 0; j < Ndim; j++)
        y_local[j] += Ai[j] * tmp_i;
    }

    /* Reduction: combine each thread's y_local into the shared y.
     * Cost is O(Ndim * #threads), negligible compared to the main
     * O(Mdim * Ndim) kernel.
     *
     * When compiled without OpenMP, this executes once and simply
     * copies y_local into y (which was zeroed above).
     */
#pragma omp critical
    {
      for (j = 0; j < Ndim; j++)
        y[j] += y_local[j];
    }
  }
#pragma endscop
}


